ALTER TABLE projects ADD COLUMN IF NOT EXISTS address TEXT;
ALTER TABLE projects ADD COLUMN IF NOT EXISTS created_at TIMESTAMPTZ NOT NULL DEFAULT now();
ALTER TABLE projects ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT now();
ALTER TABLE units ADD COLUMN IF NOT EXISTS facing VARCHAR(40);
ALTER TABLE units ADD COLUMN IF NOT EXISTS parking VARCHAR(120);
ALTER TABLE units ADD COLUMN IF NOT EXISTS amenities VARCHAR(1000);
ALTER TABLE units ADD COLUMN IF NOT EXISTS reserved_until TIMESTAMPTZ;
ALTER TABLE units ADD COLUMN IF NOT EXISTS deleted_at TIMESTAMPTZ;
ALTER TABLE units ADD COLUMN IF NOT EXISTS updated_at TIMESTAMPTZ NOT NULL DEFAULT now();
CREATE TABLE IF NOT EXISTS project_wings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE, code VARCHAR(40) NOT NULL, name VARCHAR(120) NOT NULL, UNIQUE(project_id,code));
CREATE TABLE IF NOT EXISTS project_floors (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), wing_id UUID NOT NULL REFERENCES project_wings(id) ON DELETE CASCADE, floor_number INT NOT NULL, label VARCHAR(60), UNIQUE(wing_id,floor_number));
CREATE TABLE IF NOT EXISTS unit_price_history (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), unit_id UUID NOT NULL REFERENCES units(id) ON DELETE CASCADE, old_price NUMERIC(15,2), new_price NUMERIC(15,2) NOT NULL, reason VARCHAR(300), changed_by UUID REFERENCES users(id), changed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS unit_status_history (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), unit_id UUID NOT NULL REFERENCES units(id) ON DELETE CASCADE, old_status VARCHAR(30), new_status VARCHAR(30) NOT NULL, reason VARCHAR(300), changed_by UUID REFERENCES users(id), changed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS unit_reservations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), unit_id UUID NOT NULL REFERENCES units(id), reserved_by UUID NOT NULL REFERENCES users(id), expires_at TIMESTAMPTZ NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_units_status ON units(status); CREATE INDEX IF NOT EXISTS idx_units_project_status ON units(project_id,status);
